// src/services/api.js
const BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const getHeaders = () => {
  const token = localStorage.getItem('token');
  return {
    'Content-Type': 'application/json',
    ...(token ? { Authorization: `Bearer ${token}` } : {})
  };
};

const req = async (method, path, body) => {
  const opts = { method, headers: getHeaders() };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(`${BASE}${path}`, opts);
  return res.json();
};

// Auth
export const register = (d) => req('POST', '/register', d);
export const login    = (d) => req('POST', '/login', d);
export const profile  = ()  => req('GET',  '/profile');

// Products
export const getProducts = (params = {}) => {
  const qs = new URLSearchParams(params).toString();
  return req('GET', `/products${qs ? '?' + qs : ''}`);
};
export const getProduct  = (id) => req('GET', `/products/${id}`);

// Categories
export const getCategories = () => req('GET', '/categories');

// Cart
export const getCart    = ()      => req('GET',    '/cart');
export const addToCart  = (d)     => req('POST',   '/cart', d);
export const updateCart = (id, d) => req('PUT',    `/cart/${id}`, d);
export const removeCart = (id)    => req('DELETE', `/cart/${id}`);
export const clearCart  = ()      => req('DELETE', '/cart/clear');

// Orders
export const placeOrder  = (d)  => req('POST', '/orders', d);
export const myOrders    = ()   => req('GET',  '/orders/my');
export const orderDetail = (id) => req('GET',  `/orders/${id}`);
